import { test, expect } from '@playwright/test';

test('Complete purchase flow', async ({ page }) => {
  console.log('[Timeline] Navigate: Go to base URL');
  await page.goto('https://www.saucedemo.com');

  console.log('[Timeline] Login: Enter credentials and submit');
  await page.locator('[data-test="username"]').fill(process.env.TARGET_USERNAME!);
  await page.locator('[data-test="password"]').fill(process.env.TARGET_PASSWORD!);
  await page.locator('[data-test="login-button"]').click();
  await expect(page.locator('[data-test="inventory-container"]')).toBeVisible();

  console.log('[Timeline] Sort: Select Name (A to Z)');
  await page.locator('[data-test="product-sort-container"]').selectOption({ label: 'Name (A to Z)' });

  console.log('[Timeline] Add to cart: Add first two products');
  const addToCartButtons = page.locator('[data-test^="add-to-cart-"]');
  await addToCartButtons.first().click();
  await addToCartButtons.nth(1).click();

  console.log('[Timeline] Navigate: Go to cart page');
  await page.locator('[data-test="shopping-cart-link"]').click();
  await expect(page.locator('[data-test="cart-list"]')).toBeVisible();

  console.log('[Timeline] Verify: Cart contents match added products');
  const cartItems = page.locator('[data-test="inventory-item-name"]');
  await expect(cartItems).toHaveCount(2);

  console.log('[Timeline] Checkout: Proceed to checkout');
  await page.locator('[data-test="checkout"]').click();
  await expect(page.locator('[data-test="checkout-info-container"]')).toBeVisible();

  console.log('[Timeline] Fill: Enter shipping information');
  await page.locator('[data-test="firstName"]').fill('John');
  await page.locator('[data-test="lastName"]').fill('Doe');
  await page.locator('[data-test="postalCode"]').fill('12345');

  console.log('[Timeline] Continue: Go to overview page');
  await page.locator('[data-test="continue"]').click();
  await expect(page.locator('[data-test="checkout-summary-container"]')).toBeVisible();

  console.log('[Timeline] Verify: Total calculation (item total + tax)');
  const itemTotalText = await page.locator('[data-test="subtotal-label"]').textContent();
  const taxText = await page.locator('[data-test="tax-label"]').textContent();
  const totalText = await page.locator('[data-test="total-label"]').textContent();

  const itemTotal = parseFloat(itemTotalText!.replace('Item total: $', ''));
  const tax = parseFloat(taxText!.replace('Tax: $', ''));
  const total = parseFloat(totalText!.replace('Total: $', ''));

  expect(total).toBeCloseTo(itemTotal + tax, 2);

  console.log('[Timeline] Finish: Complete the order');
  await page.locator('[data-test="finish"]').click();
  await expect(page.locator('[data-test="complete-header"]')).toHaveText('Thank you for your order!');

  console.log('[Timeline] Verify: Can navigate back to products page');
  await expect(page.locator('[data-test="back-to-products"]')).toBeVisible();
  await page.locator('[data-test="back-to-products"]').click();
  await expect(page.locator('[data-test="inventory-container"]')).toBeVisible();
});

